// TokenRequestParamsFromMap creates a TokenRequestParams from a map of URL parameters.
// The parameter keys are validated against TokenParamKey enum values.
// Unknown parameter keys are silently ignored (non-strict mode).
func TokenRequestParamsFromMap(params map[string]string) (*TokenRequestParams, error) {
	result := &TokenRequestParams{}
	for key, value := range params {
		paramKey, err := ParseTokenParamKey(key)
		if err != nil {
			continue // Ignore unknown keys in non-strict mode
		}
		switch paramKey {
		case TokenParamKey_TOKEN_PARAM_KEY_CLIENT_ID:
			result.ClientId = &value
		case TokenParamKey_TOKEN_PARAM_KEY_AUD:
			result.Aud = &value
		case TokenParamKey_TOKEN_PARAM_KEY_EXP:
			if floatVal, err := strconv.ParseFloat(value, 64); err == nil {
				result.Exp = &floatVal
			}
		case TokenParamKey_TOKEN_PARAM_KEY_INCLUDE_CLAIMS:
			if value != "" {
				result.IncludeClaims = strings.Split(value, ",")
			}
		case TokenParamKey_TOKEN_PARAM_KEY_EXCLUDE_CLAIMS:
			if value != "" {
				result.ExcludeClaims = strings.Split(value, ",")
			}
		case TokenParamKey_TOKEN_PARAM_KEY_STORE_CODE:
			result.StoreCode = &value
		case TokenParamKey_TOKEN_PARAM_KEY_CODE:
			result.Code = &value
		case TokenParamKey_TOKEN_PARAM_KEY_STATE:
			result.State = &value
		case TokenParamKey_TOKEN_PARAM_KEY_REDIRECT_URI:
			result.RedirectUri = &value
		case TokenParamKey_TOKEN_PARAM_KEY_VERIFIER:
			result.Verifier = &value
		case TokenParamKey_TOKEN_PARAM_KEY_GRANT_TYPE:
			if enumVal, err := ParseGrantType(value); err == nil {
				result.GrantType = &enumVal
			}
		}
	}
	return result, nil
}

